// The scrolltext: Leonard's 2005 words (the leonard cart's), then the line
// announcing the new count, in his tone. Only the font's characters (' '..'[').
const std = @import("std");

const LEAD = " " ** 92;
pub const TEXT_2005 = "HI EVERYBODY ! ULTRA OPTIMISATION RULES, EVEN FOR STUPID RECORD ! I NEVER THOUGH I COULD DISPLAY 312 SPRITES ONE YEAR AGO !  I TOTALLY REWRITE MY PC DATABUILDER TO IMPLEMENT NEW STUFF. THEN, I CHANGE THE CLEARING DATA FORMAT TO GET SOME MEMORY LEFT AND THAT IS !THAT DISK SHOULD (I HOPE) RUN ON 520-STF,MEGASTE,TT,FALCON AND EVEN CT60. GREETINGS ARE SENT TO PHANTOM, GUNSTICK AND SOTE. YOU ALL ARE COOL OPTIMIZERS !  LEONARD/OXYGENE, 17.03.2005";
const NOW = "      ...AND THE STUPID RECORD STRIKES BACK ! {d} SPRITES = {d} TIMES 312, ALL OF THEM DRAWN EVERY FRAME, FULLSCREEN WITH EVERY BORDER OPEN AND THE BACKGROUND ON THE HARDWARE SCROLL, 60 FPS ON ZIGGY. SAME SPIRIT AS 2005 : THE DATABUILDER DOES THE THINKING, THE PLAYER JUST RUNS. EACH BALL IS GENERATED CODE, 72 MOVES AND NOT ONE MASK, ONE PLANE, NOTHING COMPUTED TWICE. WHO WANTS TO BEAT IT ?  ULTRA OPTIMISATION STILL RULES !";

pub fn full(comptime nb: u32, comptime snakes: u32) []const u8 {
    return LEAD ++ TEXT_2005 ++ std.fmt.comptimePrint(NOW, .{ nb, snakes });
}
